package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionNativeBinding.*;
import org.kanger.ContextUniversalFamilyInspection.Status;
import org.kanger.enums.StorageLifecycleErrorCode;
import org.kanger.exception.ContextProductionCommitException;

/** Mixed existential antecedents preserve common-variable constraints and independent support routes. */
final class ContextMixedExistential {
    static int checks;static final int WORK=64000000;
    static void require(boolean value,String why){++checks;if(!value)throw new AssertionError(why);}
    static List<String> facts(int mode,String sign){List<String> f=new ArrayList<>();if(mode==1||mode==3||mode==5)f.add("!"+sign+"b("+(mode==3?2:1)+");");if(mode==2||mode==4||mode==5)f.add("!"+sign+"c("+(mode==2?1:2)+");");return f;}
    static void verdict(ContextUniversalCandidate.Evaluation e,boolean safe,boolean candidateRule,String rule,String candidate,String a,List<String> routes,String deny){
        require(e.status==(safe?Status.CONSISTENT:Status.COLLISION),"scope-sensitive mixed family verdict: "+e.status+" / "+e.reason);
        if(safe){ContextUniversalFamilyModel.Certificate cert=e.qualification.certificate;require(cert!=null&&e.qualification.collision==null&&cert.cuts.size()==4,"all four cuts have complete consistent models");List<ContextUniversalUnitRounds.Receipt> receipts=new ArrayList<>();List<ContextUniversalQuotientModel.Model> models=new ArrayList<>();for(ContextUniversalFamilyModel.Cut c:cert.cuts){require(c.receipt.verified&&c.receipt.input==cert.input&&c.model.ledger==c.receipt.closureStep.input,"exact model/closure/common-frontier bindings");receipts.add(c.receipt);models.add(c.model);}require(ContextUniversalFamilyModel.certify(cert.input,receipts,models,16,65536,WORK).certified,"all-admissible-value model independently recertified");}
        else collision(e.qualification,e.artifact.foreign,e.artifact.staged,candidateRule,rule,candidate,a,routes,deny);
        List<Entry> entries=new ArrayList<>(e.artifact.staged.primary);for(Snapshot f:e.artifact.foreign)entries.addAll(f.primary);Entry whole=entries.stream().filter(v->v.statement.equals(rule)).findFirst().get();require(whole.kind==Kind.CLAUSES&&whole.witnesses()==0&&whole.clauses.size()==2,"mixed branch clauses retain a single whole rule Source");if(!candidateRule&&candidate.contains("&&"))require(e.artifact.staged.primary.stream().filter(v->v.statement.equals(candidate)&&v.clauses.size()==2).count()==1,"whole proposed conjunction remains one Source/two clauses");
    }
    static void collision(ContextUniversalFamilyInspection.Result r,List<Snapshot> foreign,Snapshot staged,boolean candidateRule,String rule,String candidate,String a,List<String> routes,String deny){
        require(r.status==Status.COLLISION&&r.certificate==null&&r.collision!=null&&!r.collision.oppositions.isEmpty(),"complete mixed-branch contradiction");Set<Source> expectedForeign=new HashSet<>();for(Snapshot f:foreign)for(Entry e:f.primary)if(e.statement.equals(deny)||(!candidateRule&&e.statement.equals(rule)))expectedForeign.add(e.source);require(expectedForeign.size()==(candidateRule?1:2),"exact whole foreign rule/Deny Sources");Set<Set<Source>> expected=new HashSet<>(),actual=new HashSet<>();if(staged!=null){Source proposed=staged.primary.stream().filter(e->e.statement.equals(candidate)).findFirst().get().source,common=staged.primary.stream().filter(e->e.statement.equals(a)).findFirst().get().source;if(candidateRule){for(Entry e:staged.primary)if(routes.contains(e.statement))expected.add(new HashSet<>(Arrays.asList(proposed,common,e.source)));}else expected.add(new HashSet<>(Arrays.asList(proposed,common)));}
        for(ContextUniversalUnitProof.Proof p:r.collision.oppositions){Set<Source> local=new HashSet<>(),other=new HashSet<>();for(Source s:p.support.sources)(s.localX?local:other).add(s);require(p.dependsOnX&&p.contradiction&&p.conclusion==null&&p.support.sources.size()==4&&local.size()==(candidateRule?3:2)&&other.equals(expectedForeign),"exact necessary four whole Sources, no mismatched/extra branch/marker Source");actual.add(local);if(staged!=null)require(expected.contains(local),"one applicable branch with exact common fact, candidate and whole rule");}
        require(actual.size()==(candidateRule?routes.size():1),"all applicable independent fact alternatives survive without splitting a whole candidate");if(staged!=null)require(actual.equals(expected),"all and only expected whole-source support alternatives");
    }
    static void one(boolean negative,boolean reverse,boolean nativePath,boolean shared,int mode,boolean candidateRule)throws Exception{
        Path dir=Files.createTempDirectory("mixed-existential-write-");System.setProperty("user.home",dir.toString());String s=negative?"~":"",op=negative?"":"~",a="!"+s+"a(1);",deny="!"+op+"q();",rule=shared?"!($x ("+s+"a(x)&&("+s+"b(x)||"+s+"c(x))))->"+s+"q();":"!(($x "+s+"a(x))&&(($y "+s+"b(y))||($z "+s+"c(z))))->"+s+"q();";List<String> facts=facts(mode,s),routes=new ArrayList<>();for(String f:facts)if(!shared||f.contains("(1)"))routes.add(f);boolean safe=routes.isEmpty();String candidate=candidateRule?rule:mode==0?"!safe(1);":mode==5?"!"+s+"b(1)&&"+s+"c(2);":facts.get(0);
        ContextSevenPremiseNativeWriteRunner.create(dir,"Bridge",candidateRule?"!bridgeMarker(2);":rule);ContextSevenPremiseNativeWriteRunner.create(dir,"Deny",deny);ContextSevenPremiseNativeWriteRunner.create(dir,"Other","!other(2);");Set<String> settled;List<RevisionRef> pins;long afterRevision;
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){
            String base=a;if(candidateRule)for(String fact:facts)base+=" "+fact;require(f.root.compile(base,null,false),"common fact and only selected branch premises");for(String name:reverse?new String[]{"Other","Deny","Bridge"}:new String[]{"Bridge","Deny","Other"})f.db.connectContext(name);f.db.saveConnections(f.root);
            ContextProductionInventory before=ContextSevenPremiseNativeWriteRunner.inventory(f);Set<String> origins=ContextSevenPremiseNativeWriteRunner.origins(before);long revision=f.db.getRevision();int rules=f.root.getRules().size();pins=ContextSevenPremiseNativeWriteRunner.pins(f);List<String> foreignPrints;
            try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){foreignPrints=ContextForeignAntecedentQuantifier.fingerprints(lease.inventory());ContextProductionSnapshotSession.Binding bound=lease.bind(WORK,500000);require(bound.foreign.size()==3,"all private cuts bound");if(!candidateRule)require(bound.foreign.stream().flatMap(v->v.primary.stream()).filter(v->v.statement.equals(rule)&&v.clauses.size()==2).count()==1,"whole private mixed rule retained exactly once");}
            ContextUniversalCandidate.Evaluation diagnostic=f.db.qualifyUniversalProductionCandidate(f.root,candidate,1000,16,16,16,65536,1000000,WORK,500000,WORK);verdict(diagnostic,safe,candidateRule,rule,candidate,a,routes,deny);require(f.db.getRevision()==revision&&ContextSevenPremiseNativeWriteRunner.inventory(f).fingerprint.equals(before.fingerprint),"diagnostics preserve physical source");
            if(nativePath){ContextPendingNativeWrite attempt=f.db.beginUniversalWrite(f.root,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK);try{ContextProductionCommitException failure=null;try{f.root.query(candidate,null,false);}catch(ContextProductionCommitException caught){failure=caught;}if(safe)require(failure==null,"actual native scope-compatible publication");else{require(failure!=null&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&failure.getFamilyAudit()!=null&&failure.getFamilyAudit().verified&&failure.getFamilyAudit().verdict!=diagnostic.qualification,"actual native mixed conflict freshly audited");collision(failure.getFamilyAudit().verdict,diagnostic.artifact.foreign,null,candidateRule,rule,candidate,a,routes,deny);}}finally{f.db.endNativeWrite(attempt);}}
            else{DB.UniversalProductionWriteResult result=f.db.writeUniversalProductionCandidate(f.root,candidate,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK,false);require(result.status==(safe?DB.ProductionWriteStatus.PUBLISHED:DB.ProductionWriteStatus.COLLISION)&&result.trial!=diagnostic&&result.audit!=null&&result.audit.verified&&result.audit.evaluation==result.trial,"fresh exact public trial/audit governs mixed scope verdict");verdict(result.trial,safe,candidateRule,rule,candidate,a,routes,deny);require(result.before.getRevision()==revision&&result.after.getRevision()==f.db.getRevision(),"actual public physical references");}
            ContextProductionInventory after=ContextSevenPremiseNativeWriteRunner.inventory(f);settled=ContextSevenPremiseNativeWriteRunner.origins(after);afterRevision=f.db.getRevision();Set<String> expected=new HashSet<>(origins);if(safe)expected.add(candidate);require(settled.equals(expected)&&after.primary.size()==expected.size()&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"only whole proposed Source publishes, no foreign/derived primary imports");if(safe)require(afterRevision>revision,"safe publication advances revision");else require(afterRevision==revision&&f.root.getRules().size()==rules&&after.fingerprint.equals(before.fingerprint),"refusal preserves exact revision/rules/fingerprint");try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){require(ContextForeignAntecedentQuantifier.fingerprints(lease.inventory()).equals(foreignPrints),"all private initialized inventories unchanged");}
        }
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){require(f.db.getRevision()>=afterRevision&&ContextSevenPremiseNativeWriteRunner.origins(ContextSevenPremiseNativeWriteRunner.inventory(f)).equals(settled)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"ordinary durable reopen retains exact whole settled origins and pins");try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){require(lease.bind(WORK,500000).foreign.size()==3,"all private cuts bind after durable reopen");}}
    }
    static void run(boolean negative,String marker){try{for(boolean r:new boolean[]{false,true})for(boolean p:new boolean[]{false,true})for(boolean s:new boolean[]{false,true})for(int m=0;m<6;m++)for(boolean c:new boolean[]{false,true})one(negative,r,p,s,m,c);System.out.println(marker+" checks="+(checks+ContextSevenPremiseNativeWriteRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
